{"changes": [
  {"change": "modified", "requirement_id": "R-001", "new_text": "The seating position of the driver of M and N categories of vehicles as well as the seating positions of the occupants of seats in the same row as the driver seat of M and N categories of vehicles shall be equipped with a safety-belt reminder satisfying the requirements of paragraph 5.3. For vehicles of category X, the seating positions in the first row of vehicles of categories M and N shall be equipped with a safety-belt reminder satisfying the requirements of paragraph 5.3.", "new_paragraph": "5.1.1"},
  {"change": "modified", "requirement_id": "R-025", "new_text": "Safety-belt reminders for driver and occupants of seats in the same row as the driver, and, for vehicles of category X, safety-belt reminder for occupants of seat(s) of the first row, shall fulfil the requirements set out in paragraph 5.2.", "new_paragraph": "5.3.1"},
  {"change": "added", "new_text": "An ADS may manage the safety belt reminder provided that the ADS provides at least an equivalent level of safety.", "new_paragraph": "5.1.4"}
]}
